public class Main {
    public static void main(String[] args) {
        long totalRequests = 30_000_000L;
        double sloTarget = 0.999; // 99.9 percent

        double errorBudgetFraction = 1 - sloTarget;      // 0.001, i.e. 0.1 percent
        double allowedFailures = totalRequests * errorBudgetFraction;

        System.out.println(allowedFailures); // 30000.0
    }
}

